function matchScore(input: string, keywords: string[]): number {
 const lower = input.toLowerCase();
 let score = 0;
 for (const kw of keywords) {
 if (lower.includes(kw.toLowerCase())) {
 score += kw.length;
 }
 }
 return score;
}

const fallbackResponse: CopilotResponse = {
 summary:
 "I can help you with DarkOps operations intelligence. Try asking about store health, equipment status, delivery partners, refunds, fraud alerts, or daily priorities.",
 sections: [
 {
 title: "Available Topics",
 severity: "info",
 bullets: [
 "Store PulseScore analysis and trends",
 "Equipment failure tracking and maintenance",
 "Delivery partner incident management",
 "Refund statistics and anomaly detection",
 "Fraud alert review and investigation",
 "Complaint escalation analysis",
 "Daily operational priorities and focus areas",
 ],
 },
 ],
 recommendedAction: {
 title: "Try asking a specific question",
 description:
 "For example: 'Which stores need immediate attention?' or 'Summarize today's operations' or 'Show fraud alerts'.",
 priority: "low",
 },
 timestamp: now(),
};

export async function getResponse(question: string): Promise<CopilotResponse> {
 // Simulate network latency for realistic feel
 await new Promise((resolve) => setTimeout(resolve, 1200 + Math.random() * 800));

 let bestMatch: ResponseEntry | null = null;
 let bestScore = 0;

 for (const entry of responses) {
 const score = matchScore(question, entry.keywords);
 if (score > bestScore) {
 bestScore = score;
 bestMatch = entry;
 }
 }

 if (bestMatch && bestScore > 2) {
 return { ...bestMatch.response, timestamp: now() };
 }

 return { ...fallbackResponse, timestamp: now() };
}
