","/* DarkOps AI Copilot — Premium Dark Theme */

/* ===== Reset & Base ===== */
*,
*::before,
*::after {
 box-sizing: border-box;
 margin: 0;
 padding: 0;
}

.copilot-page {
 display: flex;
 flex-direction: column;
 height: 100vh;
 width: 100vw;
 background: #0a0e14;
 color: #e2e8f0;
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
 overflow: hidden;
}

/* ===== Header ===== */
.copilot-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 16px 24px;
 background: linear-gradient(180deg, #111621 0%, #0d1117 100%);
 border-bottom: 1px solid #1a2035;
 flex-shrink: 0;
}

.copilot-brand {
 display: flex;
 align-items: center;
 gap: 12px;
}

.copilot-logo {
 width: 36px;
 height: 36px;
 border-radius: 10px;
 background: linear-gradient(135deg, #8b5cf6 0%, #6366f1 50%, #3b82f6 100%);
 display: flex;
 align-items: center;
 justify-content: center;
 box-shadow: 0 0 20px rgba(139, 92, 246, 0.3);
}

.copilot-logo svg {
 width: 20px;
 height: 20px;
 fill: white;
}

.copilot-title {
 font-size: 18px;
 font-weight: 700;
 color: #f1f5f9;
 letter-spacing: -0.3px;
}

.copilot-subtitle {
 font-size: 12px;
 color: #8b5cf6;
 font-weight: 500;
 letter-spacing: 0.5px;
 text-transform: uppercase;
}

.copilot-status {
 display: flex;
 align-items: center;
 gap: 8px;
 font-size: 12px;
 color: #22c55e;
 font-weight: 500;
}

.copilot-status-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: #22c55e;
 animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
 0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.4); }
 50% { opacity: 0.8; box-shadow: 0 0 0 6px rgba(34, 197, 94, 0); }
}

/* ===== Suggested Questions ===== */
.copilot-suggestions {
 padding: 12px 24px;
 border-bottom: 1px solid #1a2035;
 flex-shrink: 0;
 overflow-x: auto;
 scrollbar-width: none;
 -ms-overflow-style: none;
}

.copilot-suggestions::-webkit-scrollbar {
 display: none;
}

.copilot-suggestions-inner {
 display: flex;
 gap: 8px;
 white-space: nowrap;
}

.copilot-chip {
 display: inline-flex;
 align-items: center;
 padding: 8px 14px;
 background: #111621;
 border: 1px solid #1e293b;
 border-radius: 20px;
 font-size: 13px;
 color: #94a3b8;
 cursor: pointer;
 transition: all 0.2s ease;
 white-space: nowrap;
 user-select: none;
}

.copilot-chip:hover {
 background: #1a2035;
 border-color: #8b5cf6;
 color: #c4b5fd;
 transform: translateY(-1px);
 box-shadow: 0 2px 8px rgba(139, 92, 246, 0.15);
}

/* ===== Conversation Area ===== */
.copilot-conversation {
 flex: 1;
 overflow-y: auto;
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 20px;
 scroll-behavior: smooth;
}

.copilot-conversation::-webkit-scrollbar {
 width: 6px;
}

.copilot-conversation::-webkit-scrollbar-track {
 background: transparent;
}

.copilot-conversation::-webkit-scrollbar-thumb {
 background: #1e293b;
 border-radius: 3px;
}

.copilot-conversation::-webkit-scrollbar-thumb:hover {
 background: #334155;
}

/* ===== Welcome Message ===== */
.copilot-welcome {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: 60px 24px;
 text-align: center;
 flex: 1;
}

.copilot-welcome-icon {
 width: 64px;
 height: 64px;
 border-radius: 16px;
 background: linear-gradient(135deg, #8b5cf6 0%, #6366f1 50%, #3b82f6 100%);
 display: flex;
 align-items: center;
 justify-content: center;
 margin-bottom: 20px;
 box-shadow: 0 0 40px rgba(139, 92, 246, 0.25);
}

.copilot-welcome-icon svg {
 width: 32px;
 height: 32px;
 fill: white;
}

.copilot-welcome h2 {
 font-size: 22px;
 font-weight: 700;
 color: #f1f5f9;
 margin-bottom: 8px;
}

.copilot-welcome p {
 font-size: 14px;
 color: #64748b;
 max-width: 420px;
 line-height: 1.6;
}

/* ===== Messages ===== */
.copilot-message {
 display: flex;
 gap: 12px;
 animation: fadeInUp 0.3s ease;
}

@keyframes fadeInUp {
 from { opacity: 0; transform: translateY(10px); }
 to { opacity: 1; transform: translateY(0); }
}

.copilot-message--user {
 flex-direction: row-reverse;
}

.copilot-message-avatar {
 width: 32px;
 height: 32px;
 border-radius: 8px;
 flex-shrink: 0;
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 12px;
 font-weight: 700;
}

.copilot-message--ai .copilot-message-avatar {
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 color: white;
}

.copilot-message--user .copilot-message-avatar {
 background: #1e293b;
 color: #94a3b8;
}

.copilot-message-content {
 max-width: 85%;
 min-width: 0;
}

.copilot-message--user .copilot-message-content {
 display: flex;
 justify-content: flex-end;
}

.copilot-user-bubble {
 background: #1e293b;
 border: 1px solid #334155;
 border-radius: 16px 16px 4px 16px;
 padding: 12px 16px;
 font-size: 14px;
 color: #e2e8f0;
 line-height: 1.5;
}

/* ===== AI Response Card ===== */
.copilot-response {
 display: flex;
 flex-direction: column;
 gap: 12px;
 width: 100%;
}

.copilot-response-summary {
 font-size: 14px;
 color: #cbd5e1;
 line-height: 1.6;
 padding: 4px 0;
}

/* ===== Section Cards ===== */
.copilot-section {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 16px;
 transition: border-color 0.2s ease;
}

.copilot-section:hover {
 border-color: #2a3555;
}

.copilot-section--critical {
 border-left: 3px solid #ef4444;
}

.copilot-section--warning {
 border-left: 3px solid #f59e0b;
}

.copilot-section--healthy {
 border-left: 3px solid #22c55e;
}

.copilot-section--info {
 border-left: 3px solid #3b82f6;
}

.copilot-section-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 12px;
}

.copilot-section-title {
 font-size: 13px;
 font-weight: 600;
 color: #f1f5f9;
 letter-spacing: -0.2px;
}

.copilot-badge {
 font-size: 11px;
 font-weight: 600;
 padding: 3px 8px;
 border-radius: 4px;
 text-transform: uppercase;
 letter-spacing: 0.3px;
}

.copilot-badge--critical {
 background: rgba(239, 68, 68, 0.15);
 color: #fca5a5;
 border: 1px solid rgba(239, 68, 68, 0.3);
}

.copilot-badge--warning {
 background: rgba(245, 158, 11, 0.15);
 color: #fcd34d;
 border: 1px solid rgba(245, 158, 11, 0.3);
}

.copilot-badge--healthy {
 background: rgba(34, 197, 94, 0.15);
 color: #86efac;
 border: 1px solid rgba(34, 197, 94, 0.3);
}

.copilot-badge--info {
 background: rgba(59, 130, 246, 0.15);
 color: #93c5fd;
 border: 1px solid rgba(59, 130, 246, 0.3);
}

/* ===== Bullet Lists ===== */
.copilot-bullets {
 list-style: none;
 display: flex;
 flex-direction: column;
 gap: 8px;
}

.copilot-bullet {
 display: flex;
 align-items: flex-start;
 gap: 8px;
 font-size: 13px;
 color: #94a3b8;
 line-height: 1.5;
}

.copilot-bullet::before {
 content: "";
 width: 5px;
 height: 5px;
 border-radius: 50%;
 background: #475569;
 flex-shrink: 0;
 margin-top: 7px;
}

.copilot-section--critical .copilot-bullet::before {
 background: #ef4444;
}

.copilot-section--warning .copilot-bullet::before {
 background: #f59e0b;
}

.copilot-section--healthy .copilot-bullet::before {
 background: #22c55e;
}

/* ===== Metrics Grid ===== */
.copilot-metrics {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
 gap: 8px;
}

.copilot-metric {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 8px 12px;
 background: #0d1117;
 border-radius: 8px;
 border: 1px solid #1a2035;
}

.copilot-metric-label {
 font-size: 11px;
 color: #64748b;
 font-weight: 500;
}

.copilot-metric-value {
 font-size: 13px;
 color: #e2e8f0;
 font-weight: 600;
 display: flex;
 align-items: center;
 gap: 4px;
}

.copilot-trend--up {
 color: #22c55e;
}

.copilot-trend--down {
 color: #ef4444;
}

.copilot-trend-icon {
 font-size: 10px;
}

/* ===== Recommended Action ===== */
.copilot-action-card {
 background: linear-gradient(135deg, rgba(139, 92, 246, 0.08) 0%, rgba(99, 102, 241, 0.05) 100%);
 border: 1px solid rgba(139, 92, 246, 0.25);
 border-radius: 12px;
 padding: 16px;
}

.copilot-action-header {
 display: flex;
 align-items: center;
 gap: 8px;
 margin-bottom: 8px;
}

.copilot-action-icon {
 width: 20px;
 height: 20px;
 border-radius: 4px;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 display: flex;
 align-items: center;
 justify-content: center;
}

.copilot-action-icon svg {
 width: 12px;
 height: 12px;
 fill: white;
}

.copilot-action-label {
 font-size: 11px;
 font-weight: 600;
 color: #a78bfa;
 text-transform: uppercase;
 letter-spacing: 0.5px;
}

.copilot-action-title {
 font-size: 14px;
 font-weight: 600;
 color: #f1f5f9;
 margin-bottom: 6px;
}

.copilot-action-description {
 font-size: 13px;
 color: #94a3b8;
 line-height: 1.6;
}

.copilot-action-priority {
 display: inline-flex;
 align-items: center;
 margin-top: 10px;
 font-size: 11px;
 font-weight: 600;
 padding: 3px 8px;
 border-radius: 4px;
 text-transform: uppercase;
 letter-spacing: 0.3px;
}

.copilot-action-priority--high {
 background: rgba(239, 68, 68, 0.15);
 color: #fca5a5;
 border: 1px solid rgba(239, 68, 68, 0.3);
}

.copilot-action-priority--medium {
 background: rgba(245, 158, 11, 0.15);
 color: #fcd34d;
 border: 1px solid rgba(245, 158, 11, 0.3);
}

.copilot-action-priority--low {
 background: rgba(59, 130, 246, 0.15);
 color: #93c5fd;
 border: 1px solid rgba(59, 130, 246, 0.3);
}

/* ===== Typing Indicator ===== */
.copilot-typing {
 display: flex;
 align-items: center;
 gap: 12px;
 animation: fadeInUp 0.3s ease;
}

.copilot-typing-dots {
 display: flex;
 align-items: center;
 gap: 4px;
 padding: 12px 16px;
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 16px;
}

.copilot-typing-dot {
 width: 7px;
 height: 7px;
 border-radius: 50%;
 background: #8b5cf6;
 animation: typing-bounce 1.4s ease-in-out infinite;
}

.copilot-typing-dot:nth-child(2) {
 animation-delay: 0.2s;
}

.copilot-typing-dot:nth-child(3) {
 animation-delay: 0.4s;
}

@keyframes typing-bounce {
 0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
 30% { transform: translateY(-6px); opacity: 1; }
}

.copilot-typing-text {
 font-size: 12px;
 color: #64748b;
 font-style: italic;
}

/* ===== Input Bar ===== */
.copilot-input-bar {
 padding: 16px 24px;
 background: #0d1117;
 border-top: 1px solid #1a2035;
 flex-shrink: 0;
}

.copilot-input-container {
 display: flex;
 align-items: center;
 gap: 12px;
 background: #111621;
 border: 1px solid #1e293b;
 border-radius: 12px;
 padding: 4px 4px 4px 16px;
 transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.copilot-input-container:focus-within {
 border-color: #8b5cf6;
 box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.1);
}

.copilot-input {
 flex: 1;
 background: transparent;
 border: none;
 outline: none;
 font-size: 14px;
 color: #e2e8f0;
 padding: 10px 0;
 font-family: inherit;
}

.copilot-input::placeholder {
 color: #475569;
}

.copilot-send-btn {
 width: 38px;
 height: 38px;
 border-radius: 8px;
 background: linear-gradient(135deg, #8b5cf6, #6366f1);
 border: none;
 cursor: pointer;
 display: flex;
 align-items: center;
 justify-content: center;
 transition: all 0.2s ease;
 flex-shrink: 0;
}

.copilot-send-btn:hover:not(:disabled) {
 transform: scale(1.05);
 box-shadow: 0 0 16px rgba(139, 92, 246, 0.4);
}

.copilot-send-btn:disabled {
 opacity: 0.4;
 cursor: not-allowed;
}

.copilot-send-btn svg {
 width: 18px;
 height: 18px;
 fill: white;
}

/* ===== Timestamp ===== */
.copilot-timestamp {
 font-size: 11px;
 color: #475569;
 margin-top: 4px;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
